INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C1','kor',2,1,'u6',1,'생활 속 정보에서 중요한 내용 찾기 — 수목원 안내판, 「공공장소에서의 예절」 광고처럼 생활 속 매체에서 꼭 알아야 할 내용과 되풀이되는 낱말(배려) 찾기',ARRAY['2국02-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C2','kor',2,1,'u6',1,'광고를 보고 생각 말하고 실천 찾기 — 광고 속 배려하는 행동과 그 까닭을 알고, 든 생각이나 느낌과 내가 생활에서 할 수 있는 배려 말하기',ARRAY['2국06-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C3','kor',2,1,'u6',3,'「줄넘기의 좋은 점」 내용 — 줄넘기를 하는 방법, 몸이 튼튼해지고·친구들과 재미있게·언제 어디서나 손쉽게 할 수 있는 까닭 찾기',ARRAY['2국02-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C4','kor',2,1,'u6',3,'중요한 내용을 찾는 방법 — 제목 살피기, 많이 나오는 낱말 찾기, 글쓴이가 알려 주고 싶은 것과 몇 가지로 설명했는지 찾아 문단마다 중요한 내용 정리하기',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C5','kor',2,1,'u6',5,'「나무뿌리는 무슨 일을 할까」 내용과 낱말 — 나무가 넘어지지 않는 까닭, 뿌리가 흙에서 얻는 것, 굵고 통통한 까닭과 고정·저장·영양분의 뜻',ARRAY['2국02-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C6','kor',2,1,'u6',5,'문단마다 중요한 내용 정리하기 — 나무뿌리가 하는 일 세 가지를 문단에서 찾아 정리하고, 새롭게 안 내용과 더 알아보고 싶은 내용 나누기',ARRAY['2국02-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C7','kor',2,1,'u6',7,'「수연이네 가족회의」 내용 — 가족회의를 한 까닭과 여행 갈 곳을 정하지 못한 까닭, 아빠·엄마·수연·수진이 가고 싶은 곳 찾기',ARRAY['2국02-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C8','kor',2,1,'u6',7,'인물의 생각과 그 까닭을 찾는 방법 — 인물이 한 말에서 생각(~하면 좋겠어요)을 찾고, 그 뒤에 나오는 좋은 점·옳은 점에서 까닭 찾기, 행동·표정에서도 찾기',ARRAY['2국02-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C9','kor',2,1,'u6',9,'「누구를 보낼까요」 인물의 생각과 까닭 — 별나라 초대장, 거북 할아버지·아기 곰·원숭이가 저마다 별나라에 가야 한다고 말한 까닭 찾기',ARRAY['2국02-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C10','kor',2,1,'u6',9,'자신의 생각을 까닭과 함께 표현하기 — 누구를 보낼지 나의 생각과 까닭을 말하고, 감사 인사·정한 동물과 까닭·끝인사를 담아 편지를 써 발표하며 서로 다른 생각 듣기',ARRAY['2국06-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C11','kor',2,1,'u6',12,'책의 중요한 내용 정리해 소개하기 — 책 소개 상자(제목·인상 깊은 장면·기억에 남는 문장·생각이나 느낌)나 책 광고, 독서 토의로 책을 소개하고 친구 작품의 잘된 점 찾기',ARRAY['2국06-02']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C12','kor',2,1,'u6',12,'「금덩이를 버린 형제」 생각과 느낌 — 아우가 금덩이를 버린 까닭과 더 소중한 것을 찾고, 떠오르는 생각을 까닭과 함께 말하기',ARRAY['2국05-02']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C13','kor',2,1,'u6',12,'토박이말 — 까치밥·볼우물·벗·여우비의 뜻을 그림과 문장으로 알고 문장에 쓰기(기초 다지기)',ARRAY['2국05-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
