INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#9','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',4,'essay','teacher','187쪽 3번 — 「공공장소에서의 예절」을 보며 든 생각이나 느낌을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C2","difficulty":4,"kind":"essay","stem":"187쪽 3번 — 「공공장소에서의 예절」을 보며 든 생각이나 느낌을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 다른 사람을 배려하는 모습이 보기 좋았다. 배려받는 사람들이 고마움을 느낄 것 같기 때문이다.","scoring_points":["생각이나 느낌을 썼어요","까닭을 썼어요"]},"explanation":["생각이나 느낌이에요.","187쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"📺","text":"「공공장소에서의 예절」 — 조용한 통화, 승강기 단추 대신 누르기, 쓰레기 줍기 장면과 「배려」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#10','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',4,'essay','teacher','187쪽 4번 — 내가 생활 속에서 남을 배려할 수 있는 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C2","difficulty":4,"kind":"essay","stem":"187쪽 4번 — 내가 생활 속에서 남을 배려할 수 있는 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 준비물을 안 가져온 친구에게 빌려준다. 무거운 짐을 든 할머니께 문을 잡아 드린다.","scoring_points":["배려할 일을 두 가지 썼어요","생활 속에서 할 수 있는 일이에요"]},"explanation":["실천이에요.","187쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#1','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C3',1,'mc','auto','「줄넘기의 좋은 점」의 제목을 보고 짐작할 수 있는 내용은?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"「줄넘기의 좋은 점」의 제목을 보고 짐작할 수 있는 내용은?","options":[{"t":"줄넘기를 하면 좋은 점","correct":true},{"t":"줄을 만드는 방법","mis":"K2-1-u6-X01"},{"t":"줄넘기 대회 날짜","mis":"K2-1-u6-X01"}],"explanation":["좋은 점이에요.","188쪽이에요.","제목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#2','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C3',1,'mc','auto','줄넘기는 어떤 운동인가요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"줄넘기는 어떤 운동인가요?","options":[{"t":"양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동","correct":true},{"t":"공을 발로 차는 운동","mis":"K2-1-u6-X03"},{"t":"물에서 하는 운동","mis":"K2-1-u6-X03"}],"explanation":["뛰어넘어요.","190쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
