INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#8','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',4,'sa','auto','「줄넘기의 좋은 점」은 줄넘기의 좋은 점을 몇 가지로 설명했나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u6-C4","difficulty":4,"kind":"sa","stem":"「줄넘기의 좋은 점」은 줄넘기의 좋은 점을 몇 가지로 설명했나요? 숫자로 쓰세요.","answer":["3","3가지","세 가지"],"explanation":["3가지예요.","190쪽이에요.","세어요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#9','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',4,'essay','teacher','191쪽 4번 — 「줄넘기의 좋은 점」의 제목과 중요한 내용 세 가지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C4","difficulty":4,"kind":"essay","stem":"191쪽 4번 — 「줄넘기의 좋은 점」의 제목과 중요한 내용 세 가지를 쓰세요.","answer_guide":{"answer":"예: 제목 — 줄넘기의 좋은 점 / 몸이 튼튼해진다. 친구들과 재미있게 할 수 있다. 언제 어디서나 손쉽게 할 수 있다.","scoring_points":["제목을 썼어요","중요한 내용 세 가지를 썼어요"]},"explanation":["정리하기예요.","191쪽이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#10','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C3',4,'essay','teacher','191쪽 5번 — 글에 나온 것 말고 내가 생각하는 줄넘기의 좋은 점을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C3","difficulty":4,"kind":"essay","stem":"191쪽 5번 — 글에 나온 것 말고 내가 생각하는 줄넘기의 좋은 점을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 줄넘기를 하면 기분이 상쾌해진다. 땀을 흘리고 나면 몸이 가벼워지기 때문이다.","scoring_points":["줄넘기의 좋은 점을 썼어요","까닭을 썼어요"]},"explanation":["내 생각이에요.","191쪽이에요.","지도서 250쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#1','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',1,'mc','auto','나무가 쉽게 넘어지지 않는 까닭은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":1,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"나무가 쉽게 넘어지지 않는 까닭은?","options":[{"t":"땅속에 있는 뿌리가 단단하게 고정해 주어서","correct":true},{"t":"잎이 무거워서","mis":"K2-1-u6-X03"},{"t":"줄기가 가늘어서","mis":"K2-1-u6-X03"}],"explanation":["뿌리가 고정해요.","195쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#2','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',1,'mc','auto','나무는 뿌리를 이용해 흙에서 무엇을 얻나요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":2,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"나무는 뿌리를 이용해 흙에서 무엇을 얻나요?","options":[{"t":"물과 영양분","correct":true},{"t":"햇빛","mis":"K2-1-u6-X03"},{"t":"돌멩이","mis":"K2-1-u6-X03"}],"explanation":["물과 영양분이에요.","195쪽 (2)예요.","예시 답안이에요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
