INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#8','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',4,'sa','auto','뿌리가 흙에서 물과 영양분을 빨아들이는 모습을 무엇에 빗대었는지 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u6-C5","difficulty":4,"kind":"sa","stem":"뿌리가 흙에서 물과 영양분을 빨아들이는 모습을 무엇에 빗대었는지 두 글자로 쓰세요.","answer":["빨대"],"explanation":["빨대예요.","195쪽이에요.","빗대었어요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#9','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C6',4,'essay','teacher','197쪽 (2) — 「나무뿌리는 무슨 일을 할까」에서 나무뿌리가 하는 일 세 가지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"197쪽 (2) — 「나무뿌리는 무슨 일을 할까」에서 나무뿌리가 하는 일 세 가지를 쓰세요.","answer_guide":{"answer":"예: 땅속에서 나무가 흔들리지 않게 잡아 준다. 흙에서 물과 영양분을 얻는다. 잎에서 만든 영양분을 모아 둔다.","scoring_points":["하는 일 세 가지를 썼어요","글의 내용과 맞아요"]},"explanation":["정리하기예요.","197쪽이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#10','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C6',4,'essay','teacher','197쪽 글과 이어 보기 — 나무뿌리에 대해 새롭게 안 내용과 더 알아보고 싶은 내용을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"197쪽 글과 이어 보기 — 나무뿌리에 대해 새롭게 안 내용과 더 알아보고 싶은 내용을 하나씩 쓰세요.","answer_guide":{"answer":"예: 새롭게 안 내용 — 뿌리가 영양분을 모아 둔다. / 더 알고 싶은 내용 — 빨아들인 영양분이 잎까지 어떻게 이동하는지","scoring_points":["새롭게 안 내용을 썼어요","더 알아보고 싶은 내용을 썼어요"]},"explanation":["글과 이어 보기예요.","197쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#1','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',1,'mc','auto','수연이네 가족이 회의한 까닭은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":1,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"수연이네 가족이 회의한 까닭은?","options":[{"t":"가족여행을 어디로 갈지 정하려고","correct":true},{"t":"집 청소를 나누려고","mis":"K2-1-u6-X03"},{"t":"생일 선물을 고르려고","mis":"K2-1-u6-X03"}],"explanation":["여행 장소예요.","201쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
