INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#8','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',4,'sa','auto','엄마께서 여행 가고 싶은 곳을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u6-C7","difficulty":4,"kind":"sa","stem":"엄마께서 여행 가고 싶은 곳을 한 글자로 쓰세요.","answer":["산"],"explanation":["산이에요.","199쪽이에요.","엄마의 말이에요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#9','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C10',4,'essay','teacher','내가 여행 가고 싶은 곳과 그 까닭을 「왜냐하면 ~ 때문이다.」를 넣어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C10","difficulty":4,"kind":"essay","stem":"내가 여행 가고 싶은 곳과 그 까닭을 「왜냐하면 ~ 때문이다.」를 넣어 쓰세요.","answer_guide":{"answer":"예: 나는 바다에 가고 싶다. 왜냐하면 조개를 줍고 파도 소리를 듣고 싶기 때문이다.","scoring_points":["가고 싶은 곳을 썼어요","까닭을 썼어요"]},"explanation":["나의 생각이에요.","지도서 259쪽이에요.","자신의 생각 나누기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
