INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#3','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C10',3,'ox','auto','「나는 원숭이가 가야 한다고 생각해. 왜냐하면 원숭이는 바나나를 좋아하니까.」는 생각을 잘 뒷받침하는 까닭이다.',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":3,"concept":"K2-1-u6-C10","difficulty":3,"kind":"ox","stem":"「나는 원숭이가 가야 한다고 생각해. 왜냐하면 원숭이는 바나나를 좋아하니까.」는 생각을 잘 뒷받침하는 까닭이다.","answer":"X","reason_options":[{"t":"바나나를 좋아하는 것은 지구를 대표해 별나라에 가는 일과 관계없는 까닭이라서","correct":true},{"t":"좋아하는 것이 있으면 늘 좋은 까닭이라서","mis":"K2-1-u6-X15"}],"mis":"K2-1-u6-X15","explanation":["이어지는 까닭이에요.","208쪽이에요.","초대장 내용을 떠올려요."],"asset":{"type":"scene","icon":"⭐","text":"「누구를 보낼까요」(이형래) — 별나라 초대장에 거북 할아버지·아기 곰·원숭이가 저마다 가겠다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
