INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#9','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C10',4,'essay','teacher','209쪽 — 별나라에 보낼 동물을 정해 감사 인사, 정한 동물과 까닭, 끝인사를 넣어 편지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C10","difficulty":4,"kind":"essay","stem":"209쪽 — 별나라에 보낼 동물을 정해 감사 인사, 정한 동물과 까닭, 끝인사를 넣어 편지를 쓰세요.","answer_guide":{"answer":"예: 별나라에 초대해 주셔서 고맙습니다. 우리는 아기 곰을 보내기로 정했습니다. 아기 곰은 지구를 많이 사랑해서 지구를 잘 알려 드릴 것입니다. 그럼 안녕히 계세요.","scoring_points":["감사 인사와 끝인사를 썼어요","정한 동물과 까닭을 썼어요"]},"explanation":["편지예요.","209쪽 보기예요.","붙임 4예요."],"asset":{"type":"scene","icon":"⭐","text":"「누구를 보낼까요」(이형래) — 별나라 초대장에 거북 할아버지·아기 곰·원숭이가 저마다 가겠다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#10','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C10',4,'essay','teacher','지도서 275쪽 평가 — 『토끼와 거북』에서 잠자는 토끼를 깨우지 않은 거북의 행동에 대한 나의 생각과 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C10","difficulty":4,"kind":"essay","stem":"지도서 275쪽 평가 — 『토끼와 거북』에서 잠자는 토끼를 깨우지 않은 거북의 행동에 대한 나의 생각과 까닭을 쓰세요.","answer_guide":{"answer":"예: 거북이 토끼를 깨웠어야 한다고 생각한다. 함께 경주하는 친구가 실수할 때 모른 척하는 것은 정정당당하지 않기 때문이다.","scoring_points":["나의 생각을 썼어요","생각을 뒷받침하는 까닭을 썼어요"]},"explanation":["평가 자료 2예요.","지도서 275쪽이에요.","정답은 하나가 아니에요."],"asset":{"type":"speech","turns":[{"who":"다솜","text":"거북이 토끼를 깨우지 않은 것은 옳다고 생각해. 경주니까 상대가 실수해도 어쩔 수 없어."},{"who":"하윤","text":"난 거북이 옳지 않다고 생각해. 친구가 실수하는데 모른 척하는 건 정정당당하지 않아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#1','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C11',1,'mc','auto','책 소개 상자의 앞면에 쓰는 것은?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":1,"concept":"K2-1-u6-C11","difficulty":1,"kind":"mc","stem":"책 소개 상자의 앞면에 쓰는 것은?","options":[{"t":"책의 제목과 인상 깊은 장면","correct":true},{"t":"내 전화번호","mis":"K2-1-u6-X13"},{"t":"책을 산 가게","mis":"K2-1-u6-X13"}],"explanation":["제목과 장면이에요.","210쪽이에요.","이런 활동 어때요예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#2','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C12',1,'mc','auto','형제가 산길에서 발견한 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":2,"concept":"K2-1-u6-C12","difficulty":1,"kind":"mc","stem":"형제가 산길에서 발견한 것은?","options":[{"t":"금덩이 두 개","correct":true},{"t":"밤 다섯 개","mis":"K2-1-u6-X03"},{"t":"나무 한 짐","mis":"K2-1-u6-X03"}],"explanation":["금덩이예요.","213쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#3','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C12',1,'mc','auto','아우가 금덩이보다 더 소중하게 생각한 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":3,"concept":"K2-1-u6-C12","difficulty":1,"kind":"mc","stem":"아우가 금덩이보다 더 소중하게 생각한 것은?","options":[{"t":"형님","correct":true},{"t":"배","mis":"K2-1-u6-X03"},{"t":"집","mis":"K2-1-u6-X03"}],"explanation":["형님이에요.","213쪽 (3)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
