INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#10','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C4',3,'mc','auto','평가 자료 — 「꿀벌의 춤」에서 꿀벌이 춤을 추며 알려 주는 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":10,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"평가 자료 — 「꿀벌의 춤」에서 꿀벌이 춤을 추며 알려 주는 것은?","options":[{"t":"꽃꿀이 있는 위치","correct":true},{"t":"꿀벌의 나이","mis":"K2-1-u6-X03"},{"t":"비가 올 날","mis":"K2-1-u6-X03"}],"explanation":["꽃꿀의 위치예요.","지도서 273쪽이에요.","평가 자료 1이에요."],"asset":{"type":"passage","lines":["꿀벌은 춤을 추면서 서로에게 꽃꿀이 있는 위치를 알려 줍니다.","꿀벌의 춤은 원형춤과 8자춤으로 나눌 수 있습니다.","원형춤은 꽃이 가까운 곳에 있을 때, 8자춤은 꽃이 멀리 있을 때 추는 춤입니다."],"title":"지도서 273쪽 평가 「꿀벌의 춤」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
