INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#6','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C12',3,'mc','auto','형이 금덩이를 강물에 던진 까닭으로 알맞은 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":6,"concept":"K2-1-u6-C12","difficulty":3,"kind":"mc","stem":"형이 금덩이를 강물에 던진 까닭으로 알맞은 것은?","options":[{"t":"아우의 말을 듣고 부끄러워져서","correct":true},{"t":"금덩이가 가짜라서","mis":"K2-1-u6-X03"},{"t":"배가 흔들려서","mis":"K2-1-u6-X03"}],"explanation":["부끄러워서요.","212쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#7','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C11',3,'mc','auto','친구의 책 소개 상자를 감상할 때 알맞은 모습은?',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":7,"concept":"K2-1-u6-C11","difficulty":3,"kind":"mc","stem":"친구의 책 소개 상자를 감상할 때 알맞은 모습은?","options":[{"t":"잘된 점을 찾아 칭찬하고 궁금한 점을 물어요","correct":true},{"t":"내 것과 다르다고 흉봐요","mis":"K2-1-u6-X10"},{"t":"보지 않고 지나가요","mis":"K2-1-u6-X10"}],"explanation":["칭찬해요.","지도서 266쪽이에요.","감상하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#8','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C13',4,'sa','auto','「비슷한 또래로서 서로 친하게 사귀는 사람」을 뜻하는 한 글자 토박이말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u6-C13","difficulty":4,"kind":"sa","stem":"「비슷한 또래로서 서로 친하게 사귀는 사람」을 뜻하는 한 글자 토박이말을 쓰세요.","answer":["벗"],"explanation":["벗이에요.","214쪽이에요.","토박이말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#9','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C11',4,'essay','teacher','좋아하는 책 한 권을 골라 책 소개 상자에 쓸 내용(제목, 기억에 남는 문장, 생각이나 느낌)을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C11","difficulty":4,"kind":"essay","stem":"좋아하는 책 한 권을 골라 책 소개 상자에 쓸 내용(제목, 기억에 남는 문장, 생각이나 느낌)을 쓰세요.","answer_guide":{"answer":"예: 제목 — 「반짝반짝 별 이야기」 / 기억에 남는 문장 — 「별은 낮에도 하늘에 있어요.」 / 느낌 — 낮에도 별이 있다는 것이 신기했다.","scoring_points":["제목을 썼어요","기억에 남는 문장과 생각이나 느낌을 썼어요"]},"explanation":["책 소개예요.","210쪽이에요.","지도서 267쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#10','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C12',4,'essay','teacher','213쪽 3번 — 「금덩이를 버린 형제」를 읽고 떠오르는 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C12","difficulty":4,"kind":"essay","stem":"213쪽 3번 — 「금덩이를 버린 형제」를 읽고 떠오르는 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 형제가 서로를 아끼는 마음이 금덩이보다 귀하다고 생각했다. 금덩이를 버리고 오히려 우애가 더 깊어졌기 때문이다.","scoring_points":["떠오르는 생각을 썼어요","까닭을 썼어요"]},"explanation":["생각과 까닭이에요.","213쪽이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#1','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C1',1,'mc','auto','「공공장소에서의 예절」에서 되풀이하는 낱말은?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"「공공장소에서의 예절」에서 되풀이하는 낱말은?","options":[{"t":"배려","correct":true},{"t":"버스","mis":"K2-1-u6-X11"},{"t":"쓰레기","mis":"K2-1-u6-X11"}],"explanation":["배려예요.","187쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"📺","text":"「공공장소에서의 예절」 — 조용한 통화, 승강기 단추 대신 누르기, 쓰레기 줍기 장면과 「배려」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#2','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C3',1,'mc','auto','줄넘기는 어떤 운동인가요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"줄넘기는 어떤 운동인가요?","options":[{"t":"양손으로 줄의 끝을 잡고 크게 돌리며 뛰어넘는 운동","correct":true},{"t":"공을 차는 운동","mis":"K2-1-u6-X03"},{"t":"물에서 하는 운동","mis":"K2-1-u6-X03"}],"explanation":["뛰어넘어요.","190쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
