INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#4','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C5',1,'mc','auto','나무가 쉽게 넘어지지 않는 까닭은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"나무가 쉽게 넘어지지 않는 까닭은?","options":[{"t":"뿌리가 단단하게 고정해 주어서","correct":true},{"t":"잎이 무거워서","mis":"K2-1-u6-X03"},{"t":"줄기가 가늘어서","mis":"K2-1-u6-X03"}],"explanation":["고정해요.","195쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#5','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C7',1,'mc','auto','수연이네 가족이 회의한 까닭은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"수연이네 가족이 회의한 까닭은?","options":[{"t":"가족여행을 어디로 갈지 정하려고","correct":true},{"t":"청소를 나누려고","mis":"K2-1-u6-X03"},{"t":"선물을 고르려고","mis":"K2-1-u6-X03"}],"explanation":["여행 장소예요.","201쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#6','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',1,'mc','auto','인물의 생각과 그 까닭은 주로 어디에서 찾나요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"인물의 생각과 그 까닭은 주로 어디에서 찾나요?","options":[{"t":"인물이 한 말","correct":true},{"t":"그림 색깔","mis":"K2-1-u6-X08"},{"t":"쪽수","mis":"K2-1-u6-X08"}],"explanation":["인물의 말이에요.","201쪽이에요.","도우미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#7','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C9',1,'mc','auto','초대장은 어디에서 왔나요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"초대장은 어디에서 왔나요?","options":[{"t":"별나라","correct":true},{"t":"바닷속 나라","mis":"K2-1-u6-X03"},{"t":"이웃 마을","mis":"K2-1-u6-X03"}],"explanation":["별나라예요.","206쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"⭐","text":"「누구를 보낼까요」(이형래) — 별나라 초대장에 거북 할아버지·아기 곰·원숭이가 저마다 가겠다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#8','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C12',1,'mc','auto','형제가 산길에서 발견한 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":8,"concept":"K2-1-u6-C12","difficulty":1,"kind":"mc","stem":"형제가 산길에서 발견한 것은?","options":[{"t":"금덩이 두 개","correct":true},{"t":"밤 다섯 개","mis":"K2-1-u6-X03"},{"t":"나무 한 짐","mis":"K2-1-u6-X03"}],"explanation":["금덩이예요.","213쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
