INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#14','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C10',2,'mc','auto','나의 생각을 알맞게 말한 것은?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":14,"concept":"K2-1-u6-C10","difficulty":2,"kind":"mc","stem":"나의 생각을 알맞게 말한 것은?","options":[{"t":"「아기 곰이 가야 한다고 생각해. 지구를 사랑하는 마음이 가장 중요하니까.」","correct":true},{"t":"「아기 곰.」","mis":"K2-1-u6-X09"},{"t":"「아무나 가도 돼.」","mis":"K2-1-u6-X09"}],"explanation":["생각과 까닭이에요.","208쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#15','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C12',2,'mc','auto','아우가 금덩이를 강물에 던진 까닭은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":15,"concept":"K2-1-u6-C12","difficulty":2,"kind":"mc","stem":"아우가 금덩이를 강물에 던진 까닭은?","options":[{"t":"형님이 미워지고 욕심이 나서","correct":true},{"t":"금덩이가 무거워서","mis":"K2-1-u6-X03"},{"t":"물고기에게 주려고","mis":"K2-1-u6-X03"}],"explanation":["욕심이 나서요.","213쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#16','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',2,'match','auto','차례와 줄넘기의 좋은 점을 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C4","difficulty":2,"kind":"match","stem":"차례와 줄넘기의 좋은 점을 이어 보세요.","pairs":[{"l":"먼저","r":"몸이 튼튼해진다"},{"l":"다음으로","r":"친구들과 재미있게 할 수 있다"},{"l":"마지막으로","r":"언제 어디서나 손쉽게 할 수 있다"}],"mis":"K2-1-u6-X04","explanation":["세 가지예요.","191쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
