INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#19','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',3,'ox','auto','「줄넘기를 하면 심장, 뼈와 같은 것이 튼튼해집니다.」가 글 전체에서 가장 중요한 내용이다.',ARRAY['K2-1-u6-X02']::text[],false,'{"seq":19,"concept":"K2-1-u6-C4","difficulty":3,"kind":"ox","stem":"「줄넘기를 하면 심장, 뼈와 같은 것이 튼튼해집니다.」가 글 전체에서 가장 중요한 내용이다.","answer":"X","reason_options":[{"t":"이 문장은 「몸이 튼튼해진다」를 자세히 설명하는 문장이라서","correct":true},{"t":"심장이 가장 중요해서","mis":"K2-1-u6-X02"}],"mis":"K2-1-u6-X02","explanation":["덧붙인 설명이에요.","188쪽이에요.","지도서 250쪽이에요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#20','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',3,'mc','auto','「먼저」, 「다음으로」, 「마지막으로」로 시작하는 문장이 알려 주는 것은?',ARRAY['K2-1-u6-X02']::text[],false,'{"seq":20,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"「먼저」, 「다음으로」, 「마지막으로」로 시작하는 문장이 알려 주는 것은?","options":[{"t":"좋은 점이 하나씩 나온다는 것","correct":true},{"t":"글이 끝났다는 것","mis":"K2-1-u6-X02"},{"t":"그림이 바뀐다는 것","mis":"K2-1-u6-X02"}],"explanation":["차례예요.","189쪽이에요.","문단의 첫 문장이에요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#21','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',3,'mc','auto','인물의 생각과 그 까닭을 파악하며 읽으면 좋은 점은?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":21,"concept":"K2-1-u6-C8","difficulty":3,"kind":"mc","stem":"인물의 생각과 그 까닭을 파악하며 읽으면 좋은 점은?","options":[{"t":"인물과 글을 더 잘 이해하게 돼요","correct":true},{"t":"글을 빨리 끝내요","mis":"K2-1-u6-X08"},{"t":"이름을 외워요","mis":"K2-1-u6-X08"}],"explanation":["더 잘 이해해요.","지도서 258쪽이에요.","내용 파악이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#22','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C11',3,'mc','auto','책 소개 상자에 넣기 알맞은 내용끼리 모은 것은?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":22,"concept":"K2-1-u6-C11","difficulty":3,"kind":"mc","stem":"책 소개 상자에 넣기 알맞은 내용끼리 모은 것은?","options":[{"t":"책 제목 · 기억에 남는 문장 · 읽고 든 느낌","correct":true},{"t":"책 가격 · 산 날짜 · 날씨","mis":"K2-1-u6-X13"},{"t":"책 무게 · 쪽수 · 가격","mis":"K2-1-u6-X13"}],"explanation":["책 소개예요.","지도서 267쪽이에요.","참고 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#23','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C1',4,'sa','auto','「공공장소에서의 예절」에서 되풀이하는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C1","difficulty":4,"kind":"sa","stem":"「공공장소에서의 예절」에서 되풀이하는 두 글자 낱말을 쓰세요.","answer":["배려"],"explanation":["배려예요.","187쪽이에요.","되풀이 낱말이에요."],"asset":{"type":"scene","icon":"📺","text":"「공공장소에서의 예절」 — 조용한 통화, 승강기 단추 대신 누르기, 쓰레기 줍기 장면과 「배려」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#24','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',4,'essay','teacher','지도서 272~273쪽 평가 — 「꿀벌의 춤」의 제목과 중요한 내용 두 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C4","difficulty":4,"kind":"essay","stem":"지도서 272~273쪽 평가 — 「꿀벌의 춤」의 제목과 중요한 내용 두 가지를 쓰세요.","answer_guide":{"answer":"예: 제목 — 꿀벌의 춤 / 꿀벌은 춤으로 꽃꿀이 있는 위치를 알려 준다. 꿀벌의 춤에는 원형춤과 8자춤이 있다.","scoring_points":["제목을 썼어요","중요한 내용 두 가지를 썼어요"]},"explanation":["평가 자료 1이에요.","지도서 273쪽이에요.","중요한 내용이에요."],"asset":{"type":"passage","lines":["꿀벌은 춤을 추면서 서로에게 꽃꿀이 있는 위치를 알려 줍니다.","꿀벌의 춤은 원형춤과 8자춤으로 나눌 수 있습니다.","원형춤은 꽃이 가까운 곳에 있을 때, 8자춤은 꽃이 멀리 있을 때 추는 춤입니다."],"title":"지도서 273쪽 평가 「꿀벌의 춤」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#25','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C10',4,'essay','teacher','지도서 274~275쪽 평가 — 잠자는 토끼를 깨우지 않은 거북의 행동에 대한 나의 생각과 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C10","difficulty":4,"kind":"essay","stem":"지도서 274~275쪽 평가 — 잠자는 토끼를 깨우지 않은 거북의 행동에 대한 나의 생각과 까닭을 쓰세요.","answer_guide":{"answer":"예: 거북이 토끼를 깨웠어야 한다고 생각한다. 친구가 실수할 때 모른 척하는 것은 정정당당하지 않기 때문이다.","scoring_points":["나의 생각을 썼어요","생각을 뒷받침하는 까닭을 썼어요"]},"explanation":["평가 자료 2예요.","지도서 275쪽이에요.","정답은 하나가 아니에요."],"asset":{"type":"speech","turns":[{"who":"다솜","text":"거북이 토끼를 깨우지 않은 것은 옳다고 생각해. 경주니까 상대가 실수해도 어쩔 수 없어."},{"who":"하윤","text":"난 거북이 옳지 않다고 생각해. 친구가 실수하는데 모른 척하는 건 정정당당하지 않아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#1','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C2',1,'mc','auto','버스에서 배려하는 행동은?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":1,"concept":"K2-1-u6-C2","difficulty":1,"kind":"mc","stem":"버스에서 배려하는 행동은?","options":[{"t":"조용히 작은 소리로 통화해요","correct":true},{"t":"큰 소리로 통화해요","mis":"K2-1-u6-X11"},{"t":"음악을 크게 틀어요","mis":"K2-1-u6-X11"}],"explanation":["조용히요.","187쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"📺","text":"「공공장소에서의 예절」 — 조용한 통화, 승강기 단추 대신 누르기, 쓰레기 줍기 장면과 「배려」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#2','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C3',1,'mc','auto','줄넘기를 하려면 필요한 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"줄넘기를 하려면 필요한 것은?","options":[{"t":"줄과 작은 공간","correct":true},{"t":"수영장","mis":"K2-1-u6-X03"},{"t":"자전거","mis":"K2-1-u6-X03"}],"explanation":["줄과 공간이에요.","190쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#3','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C4',1,'mc','auto','중요한 내용을 찾는 방법은?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":3,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"중요한 내용을 찾는 방법은?","options":[{"t":"글에서 많이 나오는 낱말을 찾아요","correct":true},{"t":"가장 긴 낱말을 찾아요","mis":"K2-1-u6-X01"},{"t":"그림만 봐요","mis":"K2-1-u6-X01"}],"explanation":["많이 나오는 낱말이에요.","190쪽이에요.","방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#4','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',1,'mc','auto','나무는 뿌리로 흙에서 무엇을 얻나요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"나무는 뿌리로 흙에서 무엇을 얻나요?","options":[{"t":"물과 영양분","correct":true},{"t":"햇빛","mis":"K2-1-u6-X03"},{"t":"돌멩이","mis":"K2-1-u6-X03"}],"explanation":["물과 영양분이에요.","195쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#5','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',1,'mc','auto','수연이가 가고 싶은 곳은?',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"수연이가 가고 싶은 곳은?","options":[{"t":"바다","correct":true},{"t":"산","mis":"K2-1-u6-X07"},{"t":"놀이공원","mis":"K2-1-u6-X07"}],"explanation":["바다예요.","201쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#6','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',1,'mc','auto','「시골 친척 집에 가면 좋겠어요.」는 아빠의 무엇인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X08']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"「시골 친척 집에 가면 좋겠어요.」는 아빠의 무엇인가요?","options":[{"t":"생각","correct":true},{"t":"까닭","mis":"K2-1-u6-X06"},{"t":"행동","mis":"K2-1-u6-X08"}],"explanation":["생각이에요.","지도서 258쪽이에요.","~하면 좋겠어요예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#7','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C9',1,'mc','auto','별나라에 가고 싶어 한 동물은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"별나라에 가고 싶어 한 동물은?","options":[{"t":"거북 할아버지, 아기 곰, 원숭이","correct":true},{"t":"토끼, 여우, 사자","mis":"K2-1-u6-X03"},{"t":"참새, 매, 독수리","mis":"K2-1-u6-X03"}],"explanation":["세 동물이에요.","206쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"⭐","text":"「누구를 보낼까요」(이형래) — 별나라 초대장에 거북 할아버지·아기 곰·원숭이가 저마다 가겠다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#8','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C12',1,'mc','auto','아우가 금덩이보다 더 소중하게 생각한 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":8,"concept":"K2-1-u6-C12","difficulty":1,"kind":"mc","stem":"아우가 금덩이보다 더 소중하게 생각한 것은?","options":[{"t":"형님","correct":true},{"t":"배","mis":"K2-1-u6-X03"},{"t":"집","mis":"K2-1-u6-X03"}],"explanation":["형님이에요.","213쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
