INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#10','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',2,'mc','auto','「나무뿌리는 무슨 일을 할까」에서 하는 일은 모두 몇 가지인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":10,"concept":"K2-1-u6-C6","difficulty":2,"kind":"mc","stem":"「나무뿌리는 무슨 일을 할까」에서 하는 일은 모두 몇 가지인가요?","options":[{"t":"세 가지","correct":true},{"t":"한 가지","mis":"K2-1-u6-X04"},{"t":"다섯 가지","mis":"K2-1-u6-X04"}],"explanation":["세 가지예요.","197쪽이에요.","문단마다요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#11','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',2,'mc','auto','뿌리가 물과 영양분을 빨아들이는 모습을 무엇에 빗대었나요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":11,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"뿌리가 물과 영양분을 빨아들이는 모습을 무엇에 빗대었나요?","options":[{"t":"빨대","correct":true},{"t":"우산","mis":"K2-1-u6-X03"},{"t":"가위","mis":"K2-1-u6-X03"}],"explanation":["빨대예요.","195쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#12','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',2,'mc','auto','엄마가 산에 가고 싶은 까닭은?',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":12,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"엄마가 산에 가고 싶은 까닭은?","options":[{"t":"시원한 바람이 불고 다람쥐와 꽃을 볼 수 있어서","correct":true},{"t":"놀이기구를 타려고","mis":"K2-1-u6-X07"},{"t":"친척을 만나려고","mis":"K2-1-u6-X07"}],"explanation":["산의 좋은 점이에요.","201쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
