INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#20','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',3,'mc','auto','「여러분은 나무뿌리를 주의 깊게 본 적이 있나요?」의 역할은?',ARRAY['K2-1-u6-X02']::text[],false,'{"seq":20,"concept":"K2-1-u6-C6","difficulty":3,"kind":"mc","stem":"「여러분은 나무뿌리를 주의 깊게 본 적이 있나요?」의 역할은?","options":[{"t":"읽는 사람의 관심을 끄는 물음이에요","correct":true},{"t":"글에서 가장 중요한 내용이에요","mis":"K2-1-u6-X02"},{"t":"글의 마지막 정리예요","mis":"K2-1-u6-X02"}],"explanation":["관심을 끌어요.","193쪽이에요.","지도서 254쪽이에요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
