INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#22','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C11',3,'mc','auto','책 광고에 「~한 친구가 읽으면 재미있어할 것 같아요.」를 넣는 까닭은?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":22,"concept":"K2-1-u6-C11","difficulty":3,"kind":"mc","stem":"책 광고에 「~한 친구가 읽으면 재미있어할 것 같아요.」를 넣는 까닭은?","options":[{"t":"어떤 친구에게 추천하는지 알려 주려고","correct":true},{"t":"광고를 길게 하려고","mis":"K2-1-u6-X13"},{"t":"책 가격을 알리려고","mis":"K2-1-u6-X13"}],"explanation":["추천 대상이에요.","지도서 269쪽이에요.","예시 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#23','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',4,'sa','auto','뿌리가 물과 영양분을 빨아들이는 모습을 무엇에 빗대었는지 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"sa","stem":"뿌리가 물과 영양분을 빨아들이는 모습을 무엇에 빗대었는지 두 글자로 쓰세요.","answer":["빨대"],"explanation":["빨대예요.","195쪽이에요.","빗대었어요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#24','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C4',4,'essay','teacher','「줄넘기의 좋은 점」의 제목과 중요한 내용 세 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C4","difficulty":4,"kind":"essay","stem":"「줄넘기의 좋은 점」의 제목과 중요한 내용 세 가지를 쓰세요.","answer_guide":{"answer":"예: 제목 — 줄넘기의 좋은 점 / 몸이 튼튼해진다. 친구들과 재미있게 할 수 있다. 언제 어디서나 손쉽게 할 수 있다.","scoring_points":["제목을 썼어요","중요한 내용 세 가지를 썼어요"]},"explanation":["정리하기예요.","191쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#25','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',4,'essay','teacher','지도서 275쪽 평가 — 다솜이와 하윤이가 거북의 행동에 대해 한 생각과 까닭을 각각 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"지도서 275쪽 평가 — 다솜이와 하윤이가 거북의 행동에 대해 한 생각과 까닭을 각각 쓰세요.","answer_guide":{"answer":"예: 다솜 — 옳다, 경주니까 상대의 실수는 어쩔 수 없어서 / 하윤 — 옳지 않다, 모른 척하는 것은 정정당당하지 않아서","scoring_points":["두 인물의 생각을 썼어요","각각의 까닭을 썼어요"]},"explanation":["평가 자료 2예요.","지도서 275쪽이에요.","인물의 말이에요."],"asset":{"type":"speech","turns":[{"who":"다솜","text":"거북이 토끼를 깨우지 않은 것은 옳다고 생각해. 경주니까 상대가 실수해도 어쩔 수 없어."},{"who":"하윤","text":"난 거북이 옳지 않다고 생각해. 친구가 실수하는데 모른 척하는 건 정정당당하지 않아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#1','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C1',1,'mc','auto','수목원 안내판에서 알아야 할 내용은?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"수목원 안내판에서 알아야 할 내용은?","options":[{"t":"이용하는 방법과 주의할 점","correct":true},{"t":"간식 가격","mis":"K2-1-u6-X11"},{"t":"노래","mis":"K2-1-u6-X11"}],"explanation":["이용 방법이에요.","185쪽이에요.","생각 열기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#2','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C3',1,'mc','auto','줄넘기를 하면 몸이 튼튼해지는 까닭은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"줄넘기를 하면 몸이 튼튼해지는 까닭은?","options":[{"t":"몸 전체를 움직이는 운동이라서","correct":true},{"t":"줄이 길어서","mis":"K2-1-u6-X03"},{"t":"혼자 해서","mis":"K2-1-u6-X03"}],"explanation":["몸 전체예요.","188쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#3','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C4',1,'mc','auto','「줄넘기의 좋은 점」에서 가장 많이 나오는 낱말은?',ARRAY['K2-1-u6-X02']::text[],false,'{"seq":3,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"「줄넘기의 좋은 점」에서 가장 많이 나오는 낱말은?","options":[{"t":"줄넘기","correct":true},{"t":"심장","mis":"K2-1-u6-X02"},{"t":"공간","mis":"K2-1-u6-X02"}],"explanation":["줄넘기예요.","지도서 250쪽이에요.","되풀이 낱말이에요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#4','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C5',1,'mc','auto','「잘 모아서 간직함」의 뜻을 가진 낱말은?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"「잘 모아서 간직함」의 뜻을 가진 낱말은?","options":[{"t":"저장","correct":true},{"t":"고정","mis":"K2-1-u6-X05"},{"t":"영양분","mis":"K2-1-u6-X05"}],"explanation":["저장이에요.","195쪽이에요.","낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#5','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',1,'mc','auto','엄마께서 가고 싶은 곳은?',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"엄마께서 가고 싶은 곳은?","options":[{"t":"산","correct":true},{"t":"바다","mis":"K2-1-u6-X07"},{"t":"친척 집","mis":"K2-1-u6-X07"}],"explanation":["산이에요.","201쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#6','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',1,'mc','auto','「오랜만에 친척들을 만나면 반가울 거예요.」는 아빠의 무엇인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X08']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"「오랜만에 친척들을 만나면 반가울 거예요.」는 아빠의 무엇인가요?","options":[{"t":"까닭","correct":true},{"t":"가고 싶은 곳","mis":"K2-1-u6-X06"},{"t":"제목","mis":"K2-1-u6-X08"}],"explanation":["까닭이에요.","지도서 259쪽이에요.","좋은 점이에요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#7','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C9',1,'mc','auto','지구를 무척 사랑한다고 말한 동물은?',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"지구를 무척 사랑한다고 말한 동물은?","options":[{"t":"아기 곰","correct":true},{"t":"거북 할아버지","mis":"K2-1-u6-X07"},{"t":"원숭이","mis":"K2-1-u6-X07"}],"explanation":["아기 곰이에요.","204쪽이에요.","인물의 말이에요."],"asset":{"type":"scene","icon":"⭐","text":"「누구를 보낼까요」(이형래) — 별나라 초대장에 거북 할아버지·아기 곰·원숭이가 저마다 가겠다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
