INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#9','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C2',2,'mc','auto','광고를 보며 든 생각으로 알맞은 것은?',ARRAY['K2-1-u6-X11','K2-1-u6-X13']::text[],false,'{"seq":9,"concept":"K2-1-u6-C2","difficulty":2,"kind":"mc","stem":"광고를 보며 든 생각으로 알맞은 것은?","options":[{"t":"나도 남을 배려하는 생활을 실천하고 싶다","correct":true},{"t":"공공장소에서는 마음대로 해도 된다","mis":"K2-1-u6-X11"},{"t":"버스 번호가 궁금하다","mis":"K2-1-u6-X13"}],"explanation":["실천해요.","187쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#10','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C4',2,'mc','auto','글쓴이가 「줄넘기의 좋은 점」에서 알려 주고 싶은 것은?',ARRAY['K2-1-u6-X01','K2-1-u6-X03']::text[],false,'{"seq":10,"concept":"K2-1-u6-C4","difficulty":2,"kind":"mc","stem":"글쓴이가 「줄넘기의 좋은 점」에서 알려 주고 싶은 것은?","options":[{"t":"줄넘기를 하면 좋은 점","correct":true},{"t":"줄 색깔","mis":"K2-1-u6-X01"},{"t":"줄넘기가 싫은 까닭","mis":"K2-1-u6-X03"}],"explanation":["좋은 점이에요.","190쪽이에요.","글쓴이의 뜻이에요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#11','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C3',2,'mc','auto','줄넘기를 지루하지 않게 할 수 있는 까닭은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":11,"concept":"K2-1-u6-C3","difficulty":2,"kind":"mc","stem":"줄넘기를 지루하지 않게 할 수 있는 까닭은?","options":[{"t":"동작을 바꾸고 여럿이 함께 뛸 수 있어서","correct":true},{"t":"줄이 무거워서","mis":"K2-1-u6-X03"},{"t":"혼자서만 해서","mis":"K2-1-u6-X03"}],"explanation":["재미있어요.","190쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#12','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',2,'mc','auto','수진이가 놀이공원에 가고 싶은 까닭은?',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":12,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"수진이가 놀이공원에 가고 싶은 까닭은?","options":[{"t":"지난번에 못 탄 놀이기구를 모두 타고 싶어서","correct":true},{"t":"수영을 하려고","mis":"K2-1-u6-X07"},{"t":"다람쥐를 보려고","mis":"K2-1-u6-X07"}],"explanation":["아쉬웠어요.","201쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
