INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#15','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C12',2,'mc','auto','금덩이를 버린 뒤 형제는 어떻게 되었나요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":15,"concept":"K2-1-u6-C12","difficulty":2,"kind":"mc","stem":"금덩이를 버린 뒤 형제는 어떻게 되었나요?","options":[{"t":"이전보다 더 우애가 깊어졌어요","correct":true},{"t":"서로 다투었어요","mis":"K2-1-u6-X03"},{"t":"다시 금덩이를 찾았어요","mis":"K2-1-u6-X03"}],"explanation":["우애가 깊어졌어요.","212쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#16','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',2,'match','auto','인물과 가고 싶은 곳을 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C7","difficulty":2,"kind":"match","stem":"인물과 가고 싶은 곳을 이어 보세요.","pairs":[{"l":"아빠","r":"시골 친척 집"},{"l":"엄마","r":"산"},{"l":"수연","r":"바다"}],"mis":"K2-1-u6-X07","explanation":["인물의 생각이에요.","201쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
