INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#18','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C9',3,'error','auto','친구가 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#19','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C10',3,'ox','auto','「원숭이가 가야 해. 왜냐하면 원숭이는 바나나를 좋아하니까.」는 생각을 잘 뒷받침하는 까닭이다.',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":19,"concept":"K2-1-u6-C10","difficulty":3,"kind":"ox","stem":"「원숭이가 가야 해. 왜냐하면 원숭이는 바나나를 좋아하니까.」는 생각을 잘 뒷받침하는 까닭이다.","answer":"X","reason_options":[{"t":"바나나를 좋아하는 것은 지구를 대표하는 일과 관계없는 까닭이라서","correct":true},{"t":"좋아하는 것이 있으면 늘 좋은 까닭이라서","mis":"K2-1-u6-X15"}],"mis":"K2-1-u6-X15","explanation":["이어지는 까닭이에요.","208쪽이에요.","초대장이에요."],"asset":{"type":"scene","icon":"⭐","text":"「누구를 보낼까요」(이형래) — 별나라 초대장에 거북 할아버지·아기 곰·원숭이가 저마다 가겠다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#20','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C4',3,'mc','auto','「꿀벌의 춤」에서 꿀벌이 춤을 추며 알려 주는 것은?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":20,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"「꿀벌의 춤」에서 꿀벌이 춤을 추며 알려 주는 것은?","options":[{"t":"꽃꿀이 있는 위치","correct":true},{"t":"꿀벌의 나이","mis":"K2-1-u6-X03"},{"t":"비가 올 날","mis":"K2-1-u6-X03"}],"explanation":["꽃꿀의 위치예요.","지도서 273쪽이에요.","평가 자료 1이에요."],"asset":{"type":"passage","lines":["꿀벌은 춤을 추면서 서로에게 꽃꿀이 있는 위치를 알려 줍니다.","꿀벌의 춤은 원형춤과 8자춤으로 나눌 수 있습니다.","원형춤은 꽃이 가까운 곳에 있을 때, 8자춤은 꽃이 멀리 있을 때 추는 춤입니다."],"title":"지도서 273쪽 평가 「꿀벌의 춤」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#21','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C9',3,'mc','auto','국어활동 95쪽 — 「토끼의 재판」에서 토끼는 누구의 말이 옳다고 생각했나요?',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"국어활동 95쪽 — 「토끼의 재판」에서 토끼는 누구의 말이 옳다고 생각했나요?","options":[{"t":"나그네","correct":true},{"t":"호랑이","mis":"K2-1-u6-X07"},{"t":"소나무","mis":"K2-1-u6-X07"}],"explanation":["나그네예요.","국어활동 95쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#22','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C13',3,'mc','auto','「감나무에 (    )이 몇 개 남아 있다.」',ARRAY['K2-1-u6-X14']::text[],false,'{"seq":22,"concept":"K2-1-u6-C13","difficulty":3,"kind":"mc","stem":"「감나무에 (    )이 몇 개 남아 있다.」","options":[{"t":"까치밥","correct":true},{"t":"여우비","mis":"K2-1-u6-X14"},{"t":"볼우물","mis":"K2-1-u6-X14"}],"explanation":["까치밥이에요.","214쪽이에요.","예문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#23','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',4,'sa','auto','엄마께서 여행 가고 싶은 곳을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C7","difficulty":4,"kind":"sa","stem":"엄마께서 여행 가고 싶은 곳을 한 글자로 쓰세요.","answer":["산"],"explanation":["산이에요.","199쪽이에요.","엄마의 말이에요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#24','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C6',4,'essay','teacher','나무뿌리가 하는 일 세 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"나무뿌리가 하는 일 세 가지를 쓰세요.","answer_guide":{"answer":"예: 나무가 흔들리지 않게 잡아 준다. 흙에서 물과 영양분을 얻는다. 잎에서 만든 영양분을 모아 둔다.","scoring_points":["하는 일 세 가지를 썼어요","글의 내용과 맞아요"]},"explanation":["정리하기예요.","197쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["나무뿌리는 우리 눈에 잘 보이지 않지만 중요한 역할을 합니다.","나무뿌리는 땅속에서 나무가 흔들리지 않게 잡아 줍니다.","나무는 뿌리를 이용해 물과 영양분을 흙에서 얻습니다.","나무뿌리는 잎에서 만들어진 영양분을 모아 두기도 합니다. 그래서 굵고 통통하게 자랍니다."],"title":"『국어』 193~195쪽 「나무뿌리는 무슨 일을 할까」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#25','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C10',4,'essay','teacher','별나라에 보낼 동물을 정해 감사 인사, 정한 동물과 까닭, 끝인사를 넣어 편지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C10","difficulty":4,"kind":"essay","stem":"별나라에 보낼 동물을 정해 감사 인사, 정한 동물과 까닭, 끝인사를 넣어 편지를 쓰세요.","answer_guide":{"answer":"예: 초대해 주셔서 고맙습니다. 우리는 아기 곰을 보내기로 정했습니다. 아기 곰은 지구를 많이 사랑해서 지구를 잘 알려 드릴 것입니다. 안녕히 계세요.","scoring_points":["감사 인사와 끝인사를 썼어요","정한 동물과 까닭을 썼어요"]},"explanation":["편지예요.","209쪽이에요.","붙임 4예요."],"asset":{"type":"scene","icon":"⭐","text":"「누구를 보낼까요」(이형래) — 별나라 초대장에 거북 할아버지·아기 곰·원숭이가 저마다 가겠다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#1','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C2',1,'mc','auto','생활 속에서 남을 배려하는 일은?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":1,"concept":"K2-1-u6-C2","difficulty":1,"kind":"mc","stem":"생활 속에서 남을 배려하는 일은?","options":[{"t":"그네를 기다리는 친구와 번갈아 타요","correct":true},{"t":"그네를 혼자 오래 타요","mis":"K2-1-u6-X11"},{"t":"친구를 밀쳐요","mis":"K2-1-u6-X11"}],"explanation":["배려예요.","187쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#2','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C3',1,'mc','auto','「줄넘기의 좋은 점」의 제목으로 짐작할 수 있는 내용은?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"「줄넘기의 좋은 점」의 제목으로 짐작할 수 있는 내용은?","options":[{"t":"줄넘기를 하면 좋은 점","correct":true},{"t":"줄을 만드는 방법","mis":"K2-1-u6-X01"},{"t":"대회 날짜","mis":"K2-1-u6-X01"}],"explanation":["좋은 점이에요.","188쪽이에요.","제목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#3','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C4',1,'mc','auto','「줄넘기의 좋은 점」은 좋은 점을 몇 가지로 설명했나요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":3,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"「줄넘기의 좋은 점」은 좋은 점을 몇 가지로 설명했나요?","options":[{"t":"세 가지","correct":true},{"t":"한 가지","mis":"K2-1-u6-X04"},{"t":"다섯 가지","mis":"K2-1-u6-X04"}],"explanation":["세 가지예요.","190쪽이에요.","세어요."],"asset":{"type":"passage","lines":["줄넘기는 양손으로 줄의 끝을 잡고 크게 돌리면서 뛰어넘는 운동입니다.","먼저, 줄넘기를 하면 몸이 튼튼해집니다. 몸 전체를 움직이는 운동이기 때문입니다.","다음으로, 줄넘기는 친구들과 재미있게 할 수 있습니다. 여러 명이 함께 뛸 수도 있습니다.","마지막으로, 줄넘기는 언제 어디서나 손쉽게 할 수 있습니다. 줄과 작은 공간만 있으면 됩니다."],"title":"『국어』 188~189쪽 「줄넘기의 좋은 점」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#4','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C5',1,'mc','auto','「한곳에 꼭 붙어 있게 함」의 뜻을 가진 낱말은?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"「한곳에 꼭 붙어 있게 함」의 뜻을 가진 낱말은?","options":[{"t":"고정","correct":true},{"t":"저장","mis":"K2-1-u6-X05"},{"t":"영양분","mis":"K2-1-u6-X05"}],"explanation":["고정이에요.","195쪽이에요.","낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#5','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C7',1,'mc','auto','수진이가 가고 싶은 곳은?',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"수진이가 가고 싶은 곳은?","options":[{"t":"놀이공원","correct":true},{"t":"산","mis":"K2-1-u6-X07"},{"t":"바다","mis":"K2-1-u6-X07"}],"explanation":["놀이공원이에요.","201쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["아빠: 시골 친척 집에 가면 좋겠어요. 오랜만에 친척들을 만나면 반가울 거예요.","엄마: 산은 어때요? 시원한 바람을 맞고, 다람쥐와 꽃도 볼 수 있어요.","수연: 바다에 가고 싶어요. 수영도 하고 모래놀이도 할 수 있어요.","수진: 놀이공원에 가고 싶어요. 지난번에 못 탄 놀이기구를 다 타고 싶어요."],"title":"『국어』 198~200쪽 「수연이네 가족회의」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
