INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#15','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C12',2,'mc','auto','이야기를 읽고 생각을 알맞게 말한 것은?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C12","difficulty":2,"kind":"mc","stem":"이야기를 읽고 생각을 알맞게 말한 것은?","options":[{"t":"「형제의 마음이 따뜻해서 나도 동생에게 따뜻하게 대해야겠어.」","correct":true},{"t":"「금덩이가 아까워.」","mis":"K2-1-u6-X09"},{"t":"「잘 모르겠어.」","mis":"K2-1-u6-X09"}],"explanation":["생각과 까닭이에요.","213쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
