INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#19','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C1',3,'ox','auto','광고는 재미로만 보는 것이라 중요한 내용을 찾을 필요가 없다.',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":19,"concept":"K2-1-u6-C1","difficulty":3,"kind":"ox","stem":"광고는 재미로만 보는 것이라 중요한 내용을 찾을 필요가 없다.","answer":"X","reason_options":[{"t":"광고도 알려 주려는 내용이 있어서","correct":true},{"t":"광고에는 전하려는 내용이 없어서","mis":"K2-1-u6-X11"}],"mis":"K2-1-u6-X11","explanation":["알려 주는 내용이 있어요.","지도서 247쪽이에요.","매체예요."],"asset":{"type":"scene","icon":"📺","text":"「공공장소에서의 예절」 — 조용한 통화, 승강기 단추 대신 누르기, 쓰레기 줍기 장면과 「배려」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#20','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C4',3,'mc','auto','「꿀벌의 춤」에서 8자춤은 언제 추나요?',ARRAY['K2-1-u6-X03']::text[],false,'{"seq":20,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"「꿀벌의 춤」에서 8자춤은 언제 추나요?","options":[{"t":"꽃이 멀리 있을 때","correct":true},{"t":"꽃이 가까울 때","mis":"K2-1-u6-X03"},{"t":"비가 올 때","mis":"K2-1-u6-X03"}],"explanation":["멀 때예요.","지도서 273쪽이에요.","평가 자료 1이에요."],"asset":{"type":"passage","lines":["꿀벌은 춤을 추면서 서로에게 꽃꿀이 있는 위치를 알려 줍니다.","꿀벌의 춤은 원형춤과 8자춤으로 나눌 수 있습니다.","원형춤은 꽃이 가까운 곳에 있을 때, 8자춤은 꽃이 멀리 있을 때 추는 춤입니다."],"title":"지도서 273쪽 평가 「꿀벌의 춤」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#21','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C10',3,'mc','auto','가족과 생각이 다를 때 알맞은 모습은?',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":21,"concept":"K2-1-u6-C10","difficulty":3,"kind":"mc","stem":"가족과 생각이 다를 때 알맞은 모습은?","options":[{"t":"서로의 생각과 까닭을 듣고 함께 의논해요","correct":true},{"t":"내 생각만 우겨요","mis":"K2-1-u6-X10"},{"t":"말하지 않아요","mis":"K2-1-u6-X10"}],"explanation":["함께 의논해요.","200쪽이에요.","가족회의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#22','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C13',3,'mc','auto','「여우비」를 알맞게 넣은 문장은?',ARRAY['K2-1-u6-X14']::text[],false,'{"seq":22,"concept":"K2-1-u6-C13","difficulty":3,"kind":"mc","stem":"「여우비」를 알맞게 넣은 문장은?","options":[{"t":"맑은 한낮에 갑자기 여우비가 왔다.","correct":true},{"t":"여우비를 먹었다.","mis":"K2-1-u6-X14"},{"t":"여우비가 볼에 파였다.","mis":"K2-1-u6-X14"}],"explanation":["뜻에 맞아요.","214쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#23','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C13',4,'sa','auto','「서로 친하게 사귀는 사람」을 뜻하는 한 글자 토박이말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C13","difficulty":4,"kind":"sa","stem":"「서로 친하게 사귀는 사람」을 뜻하는 한 글자 토박이말을 쓰세요.","answer":["벗"],"explanation":["벗이에요.","214쪽이에요.","토박이말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#24','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C2',4,'essay','teacher','내가 생활 속에서 남을 배려할 수 있는 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C2","difficulty":4,"kind":"essay","stem":"내가 생활 속에서 남을 배려할 수 있는 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 준비물을 안 가져온 친구에게 빌려준다. 무거운 짐을 든 할머니께 문을 잡아 드린다.","scoring_points":["배려할 일을 두 가지 썼어요","생활 속에서 할 수 있어요"]},"explanation":["실천이에요.","187쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#25','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C12',4,'essay','teacher','「금덩이를 버린 형제」를 읽고 떠오르는 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C12","difficulty":4,"kind":"essay","stem":"「금덩이를 버린 형제」를 읽고 떠오르는 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 형제가 서로를 아끼는 마음이 금덩이보다 귀하다고 생각했다. 금덩이를 버리고 우애가 더 깊어졌기 때문이다.","scoring_points":["떠오르는 생각을 썼어요","까닭을 썼어요"]},"explanation":["생각과 까닭이에요.","213쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["우애가 깊은 형제가 산길에서 금덩이 두 개를 보았습니다.","배를 타고 가던 아우가 갑자기 금덩이를 강물 속으로 던져 버렸습니다.","「금덩이를 갖고 나서부터 자꾸 형님이 미워지고 욕심이 나서 버렸습니다. 저에게는 형님이 더 소중해요.」","형도 금덩이를 던져 버렸고, 형제는 이전보다 더 우애가 깊어졌습니다."],"title":"『국어』 212쪽 「금덩이를 버린 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
